
use super::*;
use semio_framework_value::{DslValue,retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn retire<T:RetireOwned>(value:T){let mut cursor=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("actual Part21 fixture retirement"));for _ in 0..100000{if cursor.terminal_is_empty(){return}let g=grant(cursor.next_demand(4096).unwrap());assert!(cursor.step(g).unwrap().progress().fits(g));}panic!("Part21 fixture retirement stalled");}
#[test]
fn original_erased_part21_sources_keep_binary_admission_and_funded_closure(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();
 for row in law["binary"].as_array().unwrap(){let text=row["value"].as_str().unwrap();let input=DslValue::Object(vec![("kind".into(),DslValue::String("binary".into())),("value".into(),DslValue::String(text.into()))]);let d=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();let source=RetainedCloneSource::admit_owned(input,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).unwrap_or_else(|_|panic!("original Part21 source")).0;let input=source.borrow().project(0,|value|value as &dyn NativeValueSource);let(mut receiver,_)=<Part21Value as NativeReceive<dyn NativeValueSource>>::begin_receive(grant(<Part21Value as NativeReceive<dyn NativeValueSource>>::receive_birth_demand())).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut construction=semio_framework_value_native_owned::native_decoding::owned::OriginalConstructionFixture;let mut refused=false;
  for _ in 0..100000{if receiver.output_ready(){break}let d=receiver.demands(input,4096).unwrap();let denied=RetainedCloneGrant{maximum_items:0,..grant(d)};assert_eq!(receiver.advance(input,&mut control,4096,denied).unwrap().progress(),Default::default());match control.with_construction_recipient(&mut construction,|control|receiver.advance(input,control,4096,grant(d))){Ok(step)=>assert!(step.progress().fits(grant(d))),Err(_)=>{refused=true;break}}}
  assert_eq!(receiver.output_ready()&&!refused,row["admitted"].as_bool().unwrap());if receiver.output_ready(){let(value,_)=receiver.take(grant(receiver.take_demand().unwrap())).unwrap().unwrap();assert!(matches!(&value,Part21Value::Binary(actual)if actual==text));retire(value);}receiver.begin_close();for _ in 0..100000{if receiver.terminal_is_empty(){break}let g=grant(receiver.close_demands(4096).unwrap());assert!(receiver.close_step(g).unwrap().progress().fits(g));}assert!(receiver.terminal_is_empty());retire(source);
 }
}
